def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}  # name -> (balance, frozen)
    history = []   # Previous states for each successful operation.
    rejected = []

    arities = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def parse_amount(token):
        if not token or any(c < "0" or c > "9" for c in token):
            return None

        # Chunk conversion also supports amounts beyond Python's
        # default limit for decimal-string-to-integer conversion.
        value = 0
        for start in range(0, len(token), 1000):
            chunk = token[start:start + 1000]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]

        if (
            verb not in arities
            or len(parts) != arities[verb]
            or any(part == "" for part in parts)
        ):
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue

            for name, previous in history.pop():
                if previous is None:
                    del accounts[name]
                else:
                    accounts[name] = previous
            continue

        if verb in ("open", "deposit", "withdraw", "transfer"):
            amount = parse_amount(parts[-1])
            if amount is None or (verb != "open" and amount == 0):
                rejected.append(index)
                continue

        name = parts[1]
        previous = accounts.get(name)

        if verb == "open":
            if previous is not None:
                rejected.append(index)
                continue

            history.append(((name, None),))
            accounts[name] = (amount, False)
            continue

        if previous is None:
            rejected.append(index)
            continue

        balance, frozen = previous

        if verb == "deposit":
            history.append(((name, previous),))
            accounts[name] = (balance + amount, frozen)

        elif verb == "withdraw":
            if frozen or balance < amount:
                rejected.append(index)
                continue

            history.append(((name, previous),))
            accounts[name] = (balance - amount, frozen)

        elif verb == "transfer":
            target = parts[2]
            target_previous = accounts.get(target)

            if (
                name == target
                or target_previous is None
                or frozen
                or balance < amount
            ):
                rejected.append(index)
                continue

            history.append(((name, previous), (target, target_previous)))
            accounts[name] = (balance - amount, frozen)
            accounts[target] = (
                target_previous[0] + amount,
                target_previous[1],
            )

        elif verb == "freeze":
            if frozen:
                rejected.append(index)
                continue

            history.append(((name, previous),))
            accounts[name] = (balance, True)

        elif verb == "unfreeze":
            if not frozen:
                rejected.append(index)
                continue

            history.append(((name, previous),))
            accounts[name] = (balance, False)

    return {
        name: state[0] for name, state in accounts.items()
    }, rejected
